export const skyGLSL=`
float hash(vec3 p){p=fract(p*.3183099+vec3(.11,.17,.13));p*=17.;return fract(p.x*p.y*p.z*(p.x+p.y+p.z));}
float noise(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);}
float fbm(vec3 p){return .55*noise(p)+.27*noise(p*2.03)+.13*noise(p*4.11)+.05*noise(p*8.3);}
vec3 stars(vec3 d,float density){vec2 uv=vec2(atan(d.x,d.z)/6.2831853+.5,asin(clamp(d.y,-1.,1.))/3.14159265+.5);vec3 result=vec3(0);for(int i=0;i<3;i++){float grid=115.*pow(2.1,float(i));vec2 cell=floor(uv*vec2(grid*2.,grid));float h=hash(vec3(cell,float(i)+4.));vec2 p=fract(uv*vec2(grid*2.,grid))-vec2(hash(vec3(cell,19.)),hash(vec3(cell,31.)));float w=max(length(fwidth(uv*vec2(grid*2.,grid)))*.33,.025);float point=exp(-dot(p,p)/(w*w));float gate=step(.975-density*.025,h);result+=mix(vec3(.51,.72,1.),vec3(1.,.79,.49),hash(vec3(cell,8.)))*point*gate*(.7+pow(h,20.)*1.6);}return result;}
vec3 galaxy(vec3 d,vec3 center){vec3 n=normalize(center),a=normalize(cross(vec3(0,1,0),n)),b=cross(n,a);float z=dot(d,n);vec2 uv=vec2(dot(d,a),dot(d,b)/.48)/max(z,.01);float r=length(uv)*6.,angle=atan(uv.y,uv.x),arm=exp(-pow(sin(angle*2.+log(r+.03)*4.),2.)*16.);return (vec3(.34,.25,.56)*arm*exp(-r*1.6)+vec3(.84,.63,.38)*exp(-r*7.))*step(.1,z);}
vec3 sky(vec3 d,float preset){vec3 g=vec3(d.x,.78*d.y+.45*d.x-.08*d.z,.90*d.z+.25*d.x);float band=exp(-abs(g.y)*7.);vec3 p=g*5.;float cloud=fbm(p),fine=fbm(p*3.7),filament=pow(max(0.,1.-abs(fine-.48)*3.),3.);vec3 tint=mix(vec3(.10,.28,.36),vec3(.32,.12,.29),smoothstep(-.7,.7,g.x));vec3 c=vec3(.002,.005,.013)+band*(tint*pow(cloud,2.)*2.4+vec3(.04,.10,.15)*filament*.6);c*=1.-smoothstep(.48,.70,fine)*band*.75;c+=stars(d,band);if(preset>1.5){c*=.55;c+=galaxy(d,vec3(-.25,.10,1.))*1.6+galaxy(d,vec3(.58,-.18,1.))*.9;}else if(preset>.5){vec3 center=normalize(vec3(.36,.08,1.))*7.;float along=dot(d,center),disc=along*along-dot(center,center)+1.25*1.25;float hit=1e3;if(disc>0.&&along>0.){hit=along-sqrt(disc);vec3 n=normalize(d*hit-center);float light=max(.03,dot(n,normalize(vec3(.8,.4,-.7))));float stripe=.5+.5*sin(n.y*65.+noise(n*12.)*3.);c=mix(vec3(.22,.18,.16),vec3(.66,.46,.26),stripe)*light*.75+vec3(.04,.08,.14)*pow(1.-max(0.,-dot(n,d)),3.);}vec3 normal=normalize(vec3(-.3,.8,.3));float den=dot(d,normal);if(abs(den)>.001){float t=dot(center,normal)/den;float r=length(d*t-center);if(t>0.&&t<hit&&r>1.5&&r<2.35){float rings=.35+.4*pow(.5+.5*sin(r*130.),2.);c=mix(c,vec3(.52,.40,.27)*rings,.8);}}}return c;}
`;
export const skyWGSL=`
fn hash(input:vec3f)->f32{var p=fract(input*.3183099+vec3f(.11,.17,.13));p*=17.;return fract(p.x*p.y*p.z*(p.x+p.y+p.z));}
fn noise(p:vec3f)->f32{let i=floor(p);var f=fract(p);f=f*f*(3.-2.*f);return mix(mix(mix(hash(i),hash(i+vec3f(1,0,0)),f.x),mix(hash(i+vec3f(0,1,0)),hash(i+vec3f(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3f(0,0,1)),hash(i+vec3f(1,0,1)),f.x),mix(hash(i+vec3f(0,1,1)),hash(i+vec3f(1,1,1)),f.x),f.y),f.z);}
fn fbm(p:vec3f)->f32{return .55*noise(p)+.27*noise(p*2.03)+.13*noise(p*4.11)+.05*noise(p*8.3);}
fn stars(d:vec3f,density:f32)->vec3f{let uv=vec2f(atan2(d.x,d.z)/6.2831853+.5,asin(clamp(d.y,-1.,1.))/3.14159265+.5);var result=vec3f(0.);for(var i=0;i<3;i++){let grid=115.*pow(2.1,f32(i));let cell=floor(uv*vec2f(grid*2.,grid));let h=hash(vec3f(cell,f32(i)+4.));let p=fract(uv*vec2f(grid*2.,grid))-vec2f(hash(vec3f(cell,19.)),hash(vec3f(cell,31.)));let w=max(length(fwidth(uv*vec2f(grid*2.,grid)))*.33,.025);let point=exp(-dot(p,p)/(w*w));let gate=step(.975-density*.025,h);result+=mix(vec3f(.51,.72,1.),vec3f(1.,.79,.49),hash(vec3f(cell,8.)))*point*gate*(.7+pow(h,20.)*1.6);}return result;}
fn galaxy(d:vec3f,center:vec3f)->vec3f{let n=normalize(center);let a=normalize(cross(vec3f(0,1,0),n));let b=cross(n,a);let z=dot(d,n);let uv=vec2f(dot(d,a),dot(d,b)/.48)/max(z,.01);let r=length(uv)*6.;let angle=atan2(uv.y,uv.x);let arm=exp(-pow(sin(angle*2.+log(r+.03)*4.),2.)*16.);return (vec3f(.34,.25,.56)*arm*exp(-r*1.6)+vec3f(.84,.63,.38)*exp(-r*7.))*step(.1,z);}
fn skyColor(d:vec3f,preset:f32)->vec3f{let g=vec3f(d.x,.78*d.y+.45*d.x-.08*d.z,.90*d.z+.25*d.x);let band=exp(-abs(g.y)*7.);let p=g*5.;let cloud=fbm(p);let fine=fbm(p*3.7);let filament=pow(max(0.,1.-abs(fine-.48)*3.),3.);let tint=mix(vec3f(.10,.28,.36),vec3f(.32,.12,.29),smoothstep(-.7,.7,g.x));var c=vec3f(.002,.005,.013)+band*(tint*pow(cloud,2.)*2.4+vec3f(.04,.10,.15)*filament*.6);c*=1.-smoothstep(.48,.70,fine)*band*.75;c+=stars(d,band);if(preset>1.5){c*=.55;c+=galaxy(d,vec3f(-.25,.10,1.))*1.6+galaxy(d,vec3f(.58,-.18,1.))*.9;}else if(preset>.5){let center=normalize(vec3f(.36,.08,1.))*7.;let along=dot(d,center);let disc=along*along-dot(center,center)+1.25*1.25;var hit=1e3;if(disc>0.&&along>0.){hit=along-sqrt(disc);let n=normalize(d*hit-center);let light=max(.03,dot(n,normalize(vec3f(.8,.4,-.7))));let stripe=.5+.5*sin(n.y*65.+noise(n*12.)*3.);c=mix(vec3f(.22,.18,.16),vec3f(.66,.46,.26),stripe)*light*.75+vec3f(.04,.08,.14)*pow(1.-max(0.,-dot(n,d)),3.);}let normal=normalize(vec3f(-.3,.8,.3));let den=dot(d,normal);if(abs(den)>.001){let t=dot(center,normal)/den;let r=length(d*t-center);if(t>0.&&t<hit&&r>1.5&&r<2.35){let rings=.35+.4*pow(.5+.5*sin(r*130.),2.);c=mix(c,vec3f(.52,.40,.27)*rings,.8);}}}return c;}
`;
